function score(str) {
    switch (str) {
      case "Disagree strongly":
          return { "score" : 1, "response" : str }
      case "Disagree a little":
          return { "score" : 2, "response" : str }
      case "Neither agree nor disagree":
          return { "score" : 3, "response" : str }
      case "Agree a little":
          return { "score" : 4, "response" : str }
      case "Agree strongly":
          return { "score" : 5, "response" : str }
      default:
          return "Invalid Response: "+ str
    }
}

