            ### SOLUTION

function userScore(input) {
    var obj = {};
	var responses = [
		"I agree!",
		"I strongly agree."
		];
	if (isNaN(input)) {return console.log("Please make sure input is a digit")}
	var response = responses[0];
	if (input >= 4) {response = responses[1]}
	obj["response"] = response;
	obj["score"] = input;
	return JSON.stringify(obj, null, 3);
}

