    def parse_to_integer(v):
        return int(v) if v.isdigit() else None

    def transform(v):
        if parse_to_integer(v) in [1,2,3,4,5]:
            return {
                "score": v,
                "response": "Neither agree nor disagree"
            }

        return {
            "score": v,
            "response": "invalid value"
        }

    def task(v):
        return transform(v)

