            function chatbot(input) {
            var score = 5; // 1 and 2 are unaware, 3-5 = aware
            var response = "Chatbot is unaware of errors and will not fix them";

            if (input.score >= 4) {
              score = input.score;
              response = "Well done!";
            }
            return {
                "score": score,
                "response": response
            };
          }

